55	/**
56	 * Pure: the values a country row is missing, taken from the defaults. Only rows that predate US-02
57	 * (currency or numberLocale missing) are backfilled; once a row has both, it is never touched, so bands
58	 * an editor emptied on purpose stay empty. Within a pre-US-02 row, only empty bands are filled.
59	 */
60	export function pricingPatch(row: PricingRow): Record<string, unknown> {
61	  const patch: Record<string, unknown> = {};
62	  if (row.currency && row.numberLocale) return patch;
63	  const defaults = PRICING_DEFAULTS[row.code ?? ''];
64	  if (!row.currency && defaults) patch.currency = defaults.currency;
65	  if (!row.numberLocale && defaults) patch.numberLocale = defaults.numberLocale;
66	  if (!row.driverAgeBands?.length) patch.driverAgeBands = DRIVER_BANDS;
67	  if (!row.vehicleAgeBands?.length) patch.vehicleAgeBands = VEHICLE_BANDS;
68	  return patch;
69	}
70	
71	const BAND_KEYS = ['driverAgeBands', 'vehicleAgeBands'];
72	
73	type DateLike = string | Date | null | undefined;
74	
75	const toTime = (d: DateLike): number => (d ? new Date(d).getTime() : Number.NaN);
76	
77	/**
78	 * Pure: whether the draft may be published after the backfill wrote to it. Publishing copies the whole draft
79	 * to the published version, so it is only safe when the draft carries no pending editor changes, i.e. it was
80	 * not modified after it was last published. Only `publishedAt` is compared: the published row's `updatedAt`
81	 * is bumped by DB-layer writes such as backfillLegalAge, which would hide a pending draft edit (R-15). A
82	 * DB-layer write can only make the draft look changed, which errs on the safe side (warning, no publish).
83	 * No published version, or unreadable dates, means do not publish (never publish a draft that was not live).
84	 */
85	export function shouldPublishAfterBackfill(input: { draftUpdatedAt: DateLike; publishedAt: DateLike }): boolean {
86	  const published = toTime(input.publishedAt);
87	  const draft = toTime(input.draftUpdatedAt);
88	  if (Number.isNaN(published) || Number.isNaN(draft)) return false;
89	  return draft <= published;
90	}
