92	type DbRow = PricingRow & {
93	  id: number;
94	  documentId: string;
95	  publishedAt?: DateLike;
96	  updatedAt?: DateLike;
97	};
98	
99	/**
100	 * Existing databases get currency, locale and bands only on rows that predate US-02, never overwriting.
101	 * Scalars are written at the DB layer on each row (draft and published alike, like backfillLegalAge). The db
102	 * layer does not manage components, so the bands go through the Document Service. In Strapi 5,
103	 * `documents().update({ status: 'published' })` writes the draft and then publishes the WHOLE draft, which
104	 * would take unpublished editor changes live. So the bands are written to the draft only, and the draft is
105	 * published afterwards only if it had no pending changes (see shouldPublishAfterBackfill); otherwise a
106	 * warning names the country, whose published version lacks the bands until an editor publishes.
107	 */
108	export async function backfillCountryPricing(strapi: Core.Strapi): Promise<void> {
109	  const rows = (await strapi.db.query(UID).findMany({
110	    populate: { driverAgeBands: true, vehicleAgeBands: true },
111	  })) as unknown as DbRow[];
112	  const byDocument = new Map<string, DbRow[]>();
113	  for (const row of rows) byDocument.set(row.documentId, [...(byDocument.get(row.documentId) ?? []), row]);
114	
115	  for (const [documentId, versions] of byDocument) {
116	    const draft = versions.find((v) => !v.publishedAt);
117	    const published = versions.find((v) => v.publishedAt);
118	    const draftUpdatedAtBefore = draft?.updatedAt;
119	
120	    let bandsPatch: Record<string, unknown> = {};
121	    for (const row of versions) {
122	      const patch = pricingPatch(row);
123	      const scalars = Object.fromEntries(Object.entries(patch).filter(([k]) => !BAND_KEYS.includes(k)));
124	      if (Object.keys(scalars).length > 0) {
125	        await strapi.db.query(UID).update({ where: { id: row.id }, data: scalars });
126	      }
127	      if (row === (draft ?? published)) {
128	        bandsPatch = Object.fromEntries(Object.entries(patch).filter(([k]) => BAND_KEYS.includes(k)));
129	      }
130	    }
131	    if (Object.keys(bandsPatch).length === 0) continue;
132	
133	    await strapi.documents(UID).update({ documentId, data: bandsPatch as never, status: 'draft' });
134	    if (!published) continue;
135	    const code = (draft ?? published).code;
136	    if (
137	      shouldPublishAfterBackfill({
138	        draftUpdatedAt: draftUpdatedAtBefore,
139	        publishedAt: published.publishedAt,
140	      })
141	    ) {
142	      await strapi.documents(UID).publish({ documentId });
143	    } else {
144	      strapi.log.warn(
145	        `Country ${code}: age bands were added to the draft only because it has unpublished changes; the published version lacks the pricing until an editor publishes it.`,
146	      );
147	    }
148	  }
149	}
