199	/**
200	 * Pure (R5): the terms to add to a country row. Only when the row has none (null, missing or []); existing
201	 * terms, even edited ones, are never overwritten. Countries without seeded terms (PE) get nothing.
202	 */
203	export function termsPatch(row: { code?: string; termsAndConditions?: unknown[] | null }): Record<string, unknown> {
204	  if (row.termsAndConditions?.length) return {};
205	  const terms = TERMS_BY_COUNTRY[row.code ?? ''];
206	  return terms ? { termsAndConditions: terms } : {};
207	}
