209	/**
210	 * Terms for existing databases (R5): written to the draft only through the Document Service, then published
211	 * only if the draft had no pending changes (same rule and R-01/R-15 lessons as backfillCountryPricing);
212	 * otherwise a warning names the country, whose published version lacks the terms until an editor publishes.
213	 */
214	export async function backfillTerms(strapi: Core.Strapi): Promise<void> {
215	  const rows = (await strapi.db.query(UID).findMany({})) as unknown as Array<
216	    DbRow & { termsAndConditions?: unknown[] | null }
217	  >;
218	  const byDocument = new Map<string, typeof rows>();
219	  for (const row of rows) byDocument.set(row.documentId, [...(byDocument.get(row.documentId) ?? []), row]);
220	
221	  for (const [documentId, versions] of byDocument) {
222	    const draft = versions.find((v) => !v.publishedAt);
223	    const published = versions.find((v) => v.publishedAt);
224	    const base = draft ?? published;
225	    if (!base) continue;
226	    const patch = termsPatch(base);
227	    if (Object.keys(patch).length === 0) continue;
228	
229	    await strapi.documents(UID).update({ documentId, data: patch as never, status: 'draft' });
230	    if (!published) continue;
231	    if (shouldPublishAfterBackfill({ draftUpdatedAt: draft?.updatedAt, publishedAt: published.publishedAt })) {
232	      await strapi.documents(UID).publish({ documentId });
233	    } else {
234	      strapi.log.warn(
235	        `Country ${base.code}: terms and conditions were added to the draft only because it has unpublished changes; the published version lacks them until an editor publishes.`,
236	      );
237	    }
238	  }
239	}
