241	async function uploadIcon(strapi: Core.Strapi, file: string, alt: string): Promise<number> {
242	  // Read from src/ (not dist/) so the SVGs do not need a build copy step.
243	  const filepath = path.join(strapi.dirs.app.root, 'src', 'seed', 'assets', file);
244	  const { size } = fs.statSync(filepath);
245	  const [uploaded] = await strapi.plugin('upload').service('upload').upload({
246	    data: { fileInfo: { name: file, alternativeText: alt, caption: alt } },
247	    files: { filepath, originalFilename: file, mimetype: 'image/svg+xml', size },
248	  });
249	  return uploaded.id;
250	}
