252	export async function seedCountries(strapi: Core.Strapi): Promise<void> {
253	  const total = await strapi.documents(UID).count({});
254	  if (total > 0) return;
255	
256	  for (const country of COUNTRIES) {
257	    const icon = country.icon ? await uploadIcon(strapi, country.icon.file, country.icon.alt) : undefined;
258	    await strapi.documents(UID).create({
259	      data: { code: country.code, name: country.name, order: country.order, active: country.active, legalAge: country.legalAge, currency: country.currency, numberLocale: country.numberLocale, driverAgeBands: DRIVER_BANDS, vehicleAgeBands: VEHICLE_BANDS, termsAndConditions: TERMS_BY_COUNTRY[country.code], icon },
260	      status: 'published',
261	    });
262	  }
263	}
