1	import type { Core } from '@strapi/strapi';
2	import { registerCountryIntegrity } from './middlewares/country-integrity';
3	import { seedAdmin } from './seed/admin';
4	import { backfillCountryPricing, backfillTerms, seedCountries } from './seed/countries';
5	import { backfillLegalAge, backfillMaskedInSummary, seedFormFields } from './seed/form-fields';
6	import { grantPublicPermissions } from './seed/permissions';
7	import { seedPlans } from './seed/plans';
8	
9	export default {
10	  register({ strapi }: { strapi: Core.Strapi }) {
11	    registerCountryIntegrity(strapi);
12	  },
13	
14	  // Idempotent: safe to run on every start.
15	  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
16	    await grantPublicPermissions(strapi);
17	    await seedCountries(strapi);
18	    await backfillLegalAge(strapi);
19	    await seedFormFields(strapi);
20	    await backfillMaskedInSummary(strapi);
21	    await backfillCountryPricing(strapi);
22	    await backfillTerms(strapi);
23	    await seedPlans(strapi);
24	    await seedAdmin(strapi);
25	  },
26	};
