1	import { describe, expect, it } from 'vitest';
2	import { TERMS_BY_COUNTRY, shouldPublishAfterBackfill, termsPatch } from './countries';
3	import { rowsNeedingMaskedFlag } from './form-fields';
4	
5	describe('US-03 · FR-014 masked flag backfill (UT-09)', () => {
6	  it('flags only documentNumber/rut rows where it is null or missing', () => {
7	    const rows = [
8	      { key: 'documentNumber', maskedInSummary: null },
9	      { key: 'rut' },
10	      { key: 'email', maskedInSummary: null },
11	      { key: 'plate' },
12	    ];
13	    expect(rowsNeedingMaskedFlag(rows).map((r) => r.key)).toEqual(['documentNumber', 'rut']);
14	  });
15	
16	  it('never overrides a value an editor set (true or false)', () => {
17	    expect(
18	      rowsNeedingMaskedFlag([
19	        { key: 'documentNumber', maskedInSummary: false },
20	        { key: 'rut', maskedInSummary: true },
21	      ]),
22	    ).toEqual([]);
23	  });
24	});
25	
26	describe('US-03 · FR-014 terms backfill (UT-09)', () => {
27	  it('adds the seeded terms when empty (null, missing or [])', () => {
28	    for (const termsAndConditions of [null, undefined, []]) {
29	      expect(termsPatch({ code: 'CO', termsAndConditions })).toEqual({ termsAndConditions: TERMS_BY_COUNTRY.CO });
30	    }
31	  });
32	
33	  it('never overwrites existing terms; CO and CL texts differ', () => {
34	    expect(termsPatch({ code: 'CL', termsAndConditions: [{ type: 'paragraph' }] })).toEqual({});
35	    expect(TERMS_BY_COUNTRY.CO).not.toEqual(TERMS_BY_COUNTRY.CL);
36	  });
37	
38	  it('adds nothing for a country without seeded terms (PE)', () => {
39	    expect(termsPatch({ code: 'PE', termsAndConditions: null })).toEqual({});
40	  });
41	
42	  it('publishes only when the draft is clean', () => {
43	    expect(shouldPublishAfterBackfill({ draftUpdatedAt: '2026-01-01T10:00:00Z', publishedAt: '2026-01-01T10:00:00Z' })).toBe(true);
44	    expect(shouldPublishAfterBackfill({ draftUpdatedAt: '2026-02-01T10:00:00Z', publishedAt: '2026-01-01T10:00:00Z' })).toBe(false);
45	  });
46	});
